    return result
def main():
    s.init();people=s.PEOPLE
    extra=L/'extra_people.json'
    if extra.exists():people+=json.loads(extra.read_text('utf-8'))
    baseline=L/'baseline.json'
    if not baseline.exists():print('BASELINE_NOT_READY',flush=True);return
    existing=json.loads(baseline.read_text('utf-8'));known={x['sha256']:x['path'] for x in existing}
